import unittest

from client import InsecureTransport, call


class Session:
    def get(self, url, *, verify):
        return {"url": url, "verify": verify}


class VendorClientTests(unittest.TestCase):
    def test_tls_verification_is_required(self):
        with self.assertRaises(InsecureTransport):
            call(Session(), "https://vendor.invalid", verify=False)

    def test_verified_call_is_forwarded(self):
        self.assertTrue(call(Session(), "https://vendor.invalid")["verify"])
